    ('lib/services/manga/sync/manga_sync_record.dart', 'ICBzdGF0aWMgU3RyaW5nIHByb2dyZXNzKFN0cmluZyB3b3JrSWQsIFN0cmluZyBjYW5vbmljYWxDaGFwdGVySWQpID0+CiAgICAgICdwcm9ncmVzczokd29ya0lkOiRjYW5vbmljYWxDaGFwdGVySWQnOwo=', ''),
